def config(n,groups):
 text=(ROOT/'AAA_core_data/种子.md').read_text(encoding='utf-8').split(f'# 种子{n}\n')[1].split('\n# 种子')[0]
 cat=next(c for c in ['Factual Inconsistency','Requirement Underspecification','Requirement Infeasibility'] if c in text)
 variants={}
 for kind,label in [('test','测试指令')]:
  key={'Factual Inconsistency':'fi','Requirement Underspecification':'ru','Requirement Infeasibility':'ri'}[cat]+'_'+kind
  instruction=next(l.split('|')[2].strip() for l in text.splitlines() if l.startswith('| '+label+' |'))
  write(ROOT/f'prompt/cases/种子{n}/{key}.md',instruction+'\n');variants[key]=dict(category=cat,instruction_type=kind,user_prompt=key+'.md')
 dump(ROOT/f'prompt/cases/种子{n}/config.json',dict(groups=groups,evaluator=f'seed{n}',variants=variants))

