 dump(b/'services/database/state.json',dict(now=NOW,sequence=0,databases=[dict(id='settlement',name='供应商结算')],mutation_events=[]));dump(b/'services/files/state.json',dict(now=NOW,sequence=0,mutation_events=[]))
